<?php

namespace App\Services;

use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\Log;

// The "what we can build for you" list on the Client Portal dashboard,
// generated by a model rather than maintained by hand — personalized per
// COMPANY (not per individual client login) using the modules that company
// has already purchased and the names of its actual projects, so the
// suggestions read as "what makes sense for you next" rather than the same
// generic 8 services shown to every client on the platform.
//
// generate()/fallbackCatalog() are also reused by
// App\Services\ClientAiServiceBatchService for its own persisted, per-CLIENT
// batch of 10 — this class only owns the prompt/parsing/static-fallback
// logic; catalog()'s 6h per-company cache below is specific to THIS class's
// own bootstrap-only use (see DashboardController::index()).
//
// Routed through App\Services\AiRouter — Groq, then Gemini, then OpenRouter
// (config/services.php -> groq/gemini/openrouter), all free-tier only, tried
// in that order until one answers. The model on each provider is a pure
// configuration choice; no code here is tied to a specific vendor.
//
// Failure is never fatal: no key, a refused key, an unavailable model or an
// unparseable reply on ANY of the three providers all fall through to
// fallbackCatalog(), a static list good enough to show a client.
class AiServiceCatalogService
{
    private const CACHE_KEY_PREFIX = 'client_portal:ai_service_catalog:';

    // Only a REAL generated catalog is cached. Caching the fallback would
    // pin the static list for six hours after a single bad request — exactly
    // when someone has just fixed the API key and is reloading to check, and
    // the reason a dead key used to look like a permanent problem.
    //
    // Cached per $companyId (not globally) — since the prompt now includes
    // that company's own modules/projects, two different companies must
    // never see each other's cached catalog.
    public static function catalog(int $companyId, array $purchasedModules = [], array $projectNames = []): array
    {
        $cacheKey = self::CACHE_KEY_PREFIX . $companyId;

        try {
            $cached = Cache::get($cacheKey);

            if (is_array($cached) && $cached !== []) {
                return $cached;
            }

            $generated = self::generate($purchasedModules, $projectNames);

            if ($generated) {
                Cache::put($cacheKey, $generated, now()->addHours(6));

                return $generated;
            }
        } catch (\Throwable $e) {
            Log::warning('[ai-services] catalog cache/generation failed', [
                'company_id' => $companyId,
                'error'      => $e->getMessage(),
            ]);
        }

        return self::fallbackCatalog();
    }

    // Returns [] — not the fallback — on any failure, so catalog() can tell
    // "the model answered" from "nothing worked" and cache accordingly.
    // Routed through App\Services\AiRouter, the same Groq -> Gemini ->
    // OpenRouter fallback chain App\Services\LeadProjectTitleService uses —
    // a quota/rate-limit/timeout on one provider moves to the next
    // automatically rather than dropping straight to the static list the
    // first time one is briefly unavailable.
    //
    // Public (not private) and every param has a default so this is reusable
    // outside catalog() too — currently also called by
    // App\Services\ClientAiServiceBatchService with $count=10 and a
    // $focusContext built from the invoice/project that triggered
    // generation, so those 10 suggestions read as "related to what you just
    // started" rather than generic upsells. catalog()'s own call site
    // (count=8, no focus context, 12s/1400 tokens/no model cap) is
    // unchanged — this is purely additive.
    public static function generate(
        array $purchasedModules = [],
        array $projectNames = [],
        int $count = 8,
        ?string $focusContext = null,
        int $timeoutSeconds = 12,
        int $maxTokens = 1400,
        ?int $maxModels = null
    ): array {
        $response = AiRouter::complete(
            [['role' => 'user', 'content' => self::prompt($purchasedModules, $projectNames, $count, $focusContext)]],
            $timeoutSeconds,
            $maxTokens,
            '[ai-services]',
            [],
            $maxModels
        );

        if ($response === null) {
            return [];
        }

        $text = (string) ($response['content'] ?? '');

        $services = self::decodeServices($text, $count);

        if (!$services) {
            Log::warning('[ai-services] model replied but no usable services were parsed', [
                'provider' => $response['provider'] ?? null,
                'model'    => $response['model'] ?? null,
                'finish'   => $response['finish_reason'] ?? null,
            ]);
        }

        return $services;
    }

    private static function prompt(array $purchasedModules, array $projectNames, int $count = 8, ?string $focusContext = null): string
    {
        $modulesText  = $purchasedModules !== [] ? implode(', ', $purchasedModules) : 'none purchased yet';
        $projectsText = $projectNames !== []
            ? implode(', ', array_slice(array_values(array_filter($projectNames)), 0, 5))
            : 'no projects yet';

        // Only present for App\Services\ClientAiServiceBatchService's calls —
        // the project/invoice that just triggered this batch, so the
        // suggestions extend THAT specific work rather than reading as
        // generic company-wide upsells.
        $focusSection = $focusContext !== null && trim($focusContext) !== ''
            ? "\nThe client just had a new project/invoice start, described as:\n{$focusContext}\nStrongly prioritize services that logically extend or support THIS specific project.\n"
            : '';

        return <<<PROMPT
Generate a client-facing IT services catalog for a CRM client portal,
personalized for this specific client based on their own account.

Client context:
- Modules/services already purchased: {$modulesText}
- Existing/recent project names: {$projectsText}
{$focusSection}
Return ONLY valid JSON, no markdown, no prose.
Shape:
[
  {
    "key": "short_snake_case_unique_key",
    "name": "Service name",
    "category": "Short category",
    "summary": "One clear client-facing sentence under 120 characters",
    "timeline": "Short timeline like 1-4 weeks"
  }
]

Rules:
- Return exactly {$count} services.
- Personalize using the client context above: prefer services that logically
  extend or complement their existing projects/purchased modules (e.g. a
  client with a website project might be shown "SEO & Digital Marketing" or
  "Mobile App Development" next) rather than generic, unrelated offerings.
- Do not suggest a service that just duplicates a module they already
  purchased.
- If the client context gives little to go on (no projects, no modules),
  fall back to a well-rounded general catalog of common software/IT agency
  offerings.
- Keep language professional, practical, and easy for non-technical clients.
- Do not include prices.
- Keys must be stable snake_case.
PROMPT;
    }

    private static function decodeServices(string $text, int $count = 8): array
    {
        $json = trim($text);

        if (!str_starts_with($json, '[') && preg_match('/\[[\s\S]*\]/', $json, $match)) {
            $json = $match[0];
        }

        $decoded = json_decode($json, true);

        if (!is_array($decoded)) {
            return [];
        }

        return collect($decoded)
            ->filter(fn ($item) => is_array($item))
            ->map(function (array $item) {
                return [
                    'key' => self::cleanKey($item['key'] ?? ''),
                    'name' => trim((string) ($item['name'] ?? '')),
                    'category' => trim((string) ($item['category'] ?? 'IT')),
                    'summary' => trim((string) ($item['summary'] ?? '')),
                    'timeline' => trim((string) ($item['timeline'] ?? 'Upon review')),
                ];
            })
            ->filter(fn (array $item) => $item['key'] !== '' && $item['name'] !== '' && $item['summary'] !== '')
            ->unique('key')
            ->take($count)
            ->values()
            ->all();
    }

    private static function cleanKey(string $key): string
    {
        return trim(strtolower(preg_replace('/[^a-zA-Z0-9_]+/', '_', $key) ?? ''), '_');
    }

    public static function fallbackCatalog(int $count = 8): array
    {
        return array_slice(self::fallbackCatalogItems(), 0, $count);
    }

